class InfectionDrugsComponent {
    constructor(router, http, mMenuPerm) {
        this.router = router;
        this.http = http;
        this.mMenuPerm = mMenuPerm;
        this.source = [];
        this.confirmed = [];
        this.displayCol = ["DrugName"];
        this.format = {
            add: "הוסף",
            remove: "מחק",
            all: "הכל",
            none: "נקה",
            draggable: true,
        };
        mMenuPerm.setRoutName("InfectionDrugs");
        setTimeout(() => {
            if (!mMenuPerm.getHasPerm()) {
                localStorage.clear();
                this.router.navigate(["login"]);
            }
        }, 2000);
    }
    ngOnInit() {
        this.getDataDrugFromServer("1");
        this.getDataDrugFromServer("0");
    }
    getDataDrugFromServer(DrugStatus) {
        this.http
            .post(src_environments_environment__WEBPACK_IMPORTED_MODULE_1__["environment"].url + "GetInfectionsDrugs", 
        //.post(environment.url + "getDrugsTbl",
        { DrugStatus: DrugStatus })
            .subscribe((Response) => {
            //debugger;
            if (DrugStatus == "1") {
                this.confirmed = Response["d"];
                console.log(this.confirmed);
                //debugger
            }
            else {
                this.source = Response["d"];
                //console.log(this.source)
                // debugger
            }
        });
    }
    submitInfectionDrug() {
        console.log(this.confirmed);
        //return
        this.http
            .post(
        //environment.url + "SubmitInfectionsDrugs",
        'http://srv-apps-prod/RCF_WS/WebService.asmx/SubmitInfectionsDrugs', {
            DrugList: this.confirmed,
        })
            .subscribe((Response) => {
            //  this.dialogRef.close("Perm Add!!")
        });
    }
}
